window.townUi = (() => {
  const esc=accountEscape,art=window.townArtwork,ui=window.shopUi,typeName=ui.typeName,sizeName=ui.sizeName;
  let data=null,timer=null,request=0,district=null,selected=null,view='shops',storeType='wine',busy=false,returnFocus=null,zoom=1,typeFilter='',listMode=false,purchaseStep=1;
  const dialog=document.createElement('dialog');dialog.className='shop-task town-purchase-dialog';dialog.setAttribute('aria-labelledby','town-purchase-title');document.body.append(dialog);
  const stateKey=()=>`jg:town:${account?.id||'guest'}`;
  function saveState(){const map=accountContent.querySelector('.town-map-scroll');const state={district,selected,view,zoom,typeFilter,listMode,x:map?.scrollLeft||0,y:map?.scrollTop||0};try{sessionStorage.setItem(stateKey(),JSON.stringify(state));}catch{}const p=new URLSearchParams();if(district)p.set('district',district);if(selected)p.set('plot',selected);if(view!=='shops')p.set('view',view);if(typeFilter)p.set('type',typeFilter);p.set('zoom',zoom);p.set('x',Math.round(state.x));p.set('y',Math.round(state.y));history.replaceState({},'','/town?'+p);}
  function stop(){if(currentAccountPage==='/town'&&data)saveState();clearInterval(timer);request++;data=null;busy=false;dialog.close();}
  async function refresh(visit,repaint=true){const current=++request,owner=account?.id,response=await fetch('/api/town',{headers:{accept:'application/json'}}),result=await response.json();if(!response.ok)throw Error(accountError(result.error));if(visit!==accountVisit||current!==request||owner!==account?.id)return;data=result;if(district&&!data.districts.some(a=>a.id===district))district=null;if(repaint)render();}
  async function load(visit){await economyReady;if(!economyFlags.businesses){data={disabled:true};return;}let saved={};try{saved=JSON.parse(sessionStorage.getItem(stateKey())||'{}');}catch{}const q=new URLSearchParams(location.search),explicit=q.size>0;district=q.get('district')||(!explicit?saved.district:null)||null;selected=q.get('plot')||(!explicit?saved.selected:null)||null;view=q.get('view')||(!explicit?saved.view:null)||'shops';typeFilter=q.get('type')||(!explicit?saved.typeFilter:null)||'';zoom=Math.min(3,Math.max(1,Number(q.get('zoom')||(!explicit?saved.zoom:null)||1)));listMode=Boolean(!explicit&&saved.listMode);await refresh(visit,false);if(visit!==accountVisit)return;const plot=data.plots.find(p=>p.id===selected);if(plot&&!q.has('zoom'))zoom=2;restore={x:Number(q.get('x')||(!explicit?saved.x:null)||0),y:Number(q.get('y')||(!explicit?saved.y:null)||0)};timer=setInterval(()=>{if(!document.hidden&&!busy&&!dialog.open&&!document.activeElement?.closest('.town-toolbar,.town-map-scroll,.town-context'))refresh(visit).catch(()=>{});},30000);}
  let restore=null;
  function visiblePlots(){return data.plots.filter(p=>(!district||p.districtId===district)&&(view!=='mine'||p.business?.own)&&(view!=='open'||!p.occupied)&&(!typeFilter||!p.occupied||p.business.type===typeFilter));}
  function plotLabel(plot){return plot.business?.name|| (plot.business?typeName(plot.business.type):`${t('Available plot','Freies Grundstück')} · ${plot.streetName}`);}
  function preview(plot){if(!plot)return `<div class="town-preview-empty">${ui.art('wine')}<h2>${t('Explore the town','Entdecke die Stadt')}</h2><p>${t('Choose a store or plot on the map or in the list.','Wähle einen Laden oder ein Grundstück auf der Karte oder in der Liste.')}</p></div>`;const b=plot.business;return `<article class="town-preview shop-color-${esc(b?.type||storeType)}"><button class="town-preview-close" data-town-clear aria-label="${t('Clear selection','Auswahl aufheben')}">×</button>${ui.art(b?.type||storeType)}<span class="shop-kicker">${b?esc(typeName(b.type)):t('Available plot','Freies Grundstück')}</span><h2>${esc(plotLabel(plot))}</h2><p>${plot.districtNumber}. ${esc(plot.districtName)} · ${esc(plot.streetName)}</p>${b?`${b.own?`<span class="shop-badge">${t('Your store','Dein Laden')}</span>`:`<p>@${esc(b.owner)}</p>`}${window.storeReputationUi?.meter(b)||''}<p>${b.stockCount} ${t('items on shelves','Artikel im Regal')}</p><a class="primary-button" href="${esc(ui.href(b))}" data-page>${b.own?t('Manage store','Laden verwalten'):t('Visit store','Laden besuchen')} →</a>`:`${metrics(plot)}<button class="primary-button" data-town-open="${esc(plot.id)}">${t('Open a store here','Hier einen Laden eröffnen')} →</button>`}</article>`;}
  function metrics(p){return `<dl class="town-plot-facts"><div><dt>${t('Size','Größe')}</dt><dd>${esc(sizeName(p.size))}</dd></div><div><dt>${t('From','Ab')}</dt><dd>${justizEuro(Math.min(...Object.values(p.costs)))}</dd></div><div><dt>${t('Foot traffic','Laufkundschaft')}</dt><dd>${number(p.trafficMultiplier,2)}×</dd></div><div><dt>${t('Level','Level')}</dt><dd>${p.requiredLevel}</dd></div></dl>`;}
  function mapPin(plot){const p=art.position(plot,data.districts),b=plot.business;return `<button type="button" class="town-pin shop-color-${esc(b?.type||'wine')} ${b?'is-store':'is-plot'} ${b?.own?'is-own':''} ${selected===plot.id?'is-selected':''}" style="left:${p.x/8.6}%;top:${p.y/7.3}%" data-town-select="${esc(plot.id)}" aria-pressed="${selected===plot.id}" aria-label="${esc(plotLabel(plot))} · ${esc(plot.streetName)}">${b?ui.art(b.type):'<span class="town-plot-plus">＋</span>'}<span class="town-pin-name">${esc(plotLabel(plot))}</span>${b?.own?'<i aria-hidden="true">★</i>':''}</button>`;}
  function render(){if(currentAccountPage!=='/town'||!data)return;if(data.disabled){accountContent.innerHTML=pageHeading(t('Town map is unavailable.','Stadtplan ist nicht verfügbar.'));return;}saveState();const old=accountContent.querySelector('.town-map-scroll'),scroll=old?{x:old.scrollLeft,y:old.scrollTop}:restore,places=visiblePlots(),plot=data.plots.find(p=>p.id===selected);accountContent.innerHTML=`<div class="town-page stores-workspace ${listMode?'is-list-mode':''}"><header class="shop-page-heading"><h1 tabindex="-1">${t('Town map','Stadtplan')}</h1><a class="secondary-button" href="/businesses" data-page>${t('Your stores','Deine Läden')} ↗</a></header><div class="town-toolbar"><div class="shop-tabs" role="group" aria-label="${t('Map filters','Kartenfilter')}">${[['shops',t('All','Alle')],['mine',t('My stores','Meine Läden')],['open',t('Available plots','Freie Grundstücke')]].map(([id,label])=>`<button data-town-view="${id}" aria-pressed="${view===id}">${label}</button>`).join('')}</div><label>${t('District','Bezirk')}<select data-town-district><option value="">${t('All districts','Alle Bezirke')}</option>${data.districts.map(a=>`<option value="${a.id}" ${district===a.id?'selected':''}>${a.number}. ${esc(a.name)}</option>`).join('')}</select></label><label>${t('Store type','Ladentyp')}<select data-town-type><option value="">${t('All types','Alle Typen')}</option>${data.types.map(a=>`<option value="${a.id}" ${typeFilter===a.id?'selected':''}>${esc(typeName(a.id))}</option>`).join('')}</select></label></div><div class="town-mobile-switch shop-tabs"><button data-town-display="map" aria-pressed="${!listMode}">${t('Map','Karte')}</button><button data-town-display="list" aria-pressed="${listMode}">${t('List','Liste')} (${places.length})</button></div><div class="town-layout"><section class="town-map-shell"><div class="town-map-controls"><div class="town-zoom"><button data-town-zoom="-1" aria-label="${t('Zoom out','Verkleinern')}" ${zoom<=1?'disabled':''}>−</button><span aria-live="polite">${[t('Town','Stadt'),t('District','Bezirk'),t('Street','Straße')][zoom-1]}</span><button data-town-zoom="1" aria-label="${t('Zoom in','Vergrößern')}" ${zoom>=3?'disabled':''}>+</button></div><button data-town-fit>${t('Fit town','Ganze Stadt')}</button><button data-town-mine>${t('Find my stores','Meine Läden finden')}</button></div><div class="town-map-scroll" tabindex="0" aria-label="${t('Town map. Drag to pan; use arrow keys to move, plus and minus to zoom.','Stadtplan. Zum Verschieben ziehen; Pfeiltasten zum Bewegen, Plus und Minus zum Zoomen.')}"><div class="town-canvas" data-zoom="${zoom}">${art.render(data,null,esc)}${places.map(mapPin).join('')}${data.districts.map(a=>{const [x,y,w,h]=a.bounds;return `<button class="town-district-chip ${district&&district!==a.id?'is-muted':''}" style="left:${(x+w/2)/8.6}%;top:${(y+34)/7.3}%" data-town-area="${a.id}"><strong>${a.number}. ${esc(a.name)}</strong><small>${data.plots.filter(p=>p.districtId===a.id&&p.occupied).length} ${t('stores','Läden')} · ${data.plots.filter(p=>p.districtId===a.id&&!p.occupied).length} ${t('plots','Grundstücke')}</small></button>`;}).join('')}</div></div><footer class="town-map-legend"><span>★ ${t('Your store','Dein Laden')}</span><span>＋ ${t('Available plot','Freies Grundstück')}</span><span>${places.length} ${t('locations','Standorte')}</span></footer></section><aside class="town-context"><div class="town-selection">${preview(plot)}</div><details class="town-place-directory" ${listMode?'open':''}><summary>${t('Locations list','Standortliste')} (${places.length})</summary><div class="town-place-list">${places.map(p=>`<button class="town-place-row ${selected===p.id?'is-selected':''}" data-town-select="${esc(p.id)}" aria-pressed="${selected===p.id}"><span class="town-list-symbol">${p.business?art.icon(p.business.type):'＋'}</span><span><strong>${esc(plotLabel(p))}</strong><small>${esc(p.streetName)} · ${esc(p.districtName)}</small></span><span aria-hidden="true">→</span></button>`).join('')||`<p class="shop-empty">${t('No matching locations.','Keine passenden Standorte.')}</p>`}</div></details></aside></div></div>`;const map=accountContent.querySelector('.town-map-scroll');sizeMap();if(scroll){map.scrollLeft=scroll.x;map.scrollTop=scroll.y;restore=null;}else if(selected)centerPlot(selected);bindPan(map);}
  const mapMetrics=new WeakMap();
  function sizeMap(){const map=accountContent.querySelector('.town-map-scroll'),canvas=map?.querySelector('.town-canvas');if(!canvas)return;const previous=mapMetrics.get(map),center=previous?{x:(map.scrollLeft+previous.width/2)/previous.worldWidth,y:(map.scrollTop+previous.height/2)/previous.worldHeight}:null;const scale=Math.max(.3,Math.min(map.clientWidth/860,map.clientHeight/730))*[1,1.8,2.8][zoom-1];canvas.style.width=`${860*scale}px`;canvas.style.height=`${730*scale}px`;if(center){map.scrollLeft=center.x*860*scale-map.clientWidth/2;map.scrollTop=center.y*730*scale-map.clientHeight/2;}mapMetrics.set(map,{width:map.clientWidth,height:map.clientHeight,worldWidth:860*scale,worldHeight:730*scale});}
  function centerPlot(id){const p=data?.plots.find(p=>p.id===id),map=accountContent.querySelector('.town-map-scroll'),canvas=map?.querySelector('.town-canvas');if(!p||!canvas)return;const point=art.position(p,data.districts);map.scrollLeft=point.x/860*canvas.clientWidth-map.clientWidth/2;map.scrollTop=point.y/730*canvas.clientHeight-map.clientHeight/2;}
  function bindPan(map){let drag=null;map.addEventListener('pointerdown',e=>{if(e.target.closest('button')||e.pointerType==='touch')return;drag={x:e.clientX,y:e.clientY,sx:map.scrollLeft,sy:map.scrollTop};map.setPointerCapture(e.pointerId);map.classList.add('is-dragging');});map.addEventListener('pointermove',e=>{if(!drag)return;map.scrollLeft=drag.sx+drag.x-e.clientX;map.scrollTop=drag.sy+drag.y-e.clientY;});map.addEventListener('pointerup',()=>{drag=null;map.classList.remove('is-dragging');saveState();});map.addEventListener('scroll',()=>{clearTimeout(map.saveTimer);map.saveTimer=setTimeout(()=>{if(currentAccountPage==='/town')saveState();},150);});map.addEventListener('keydown',e=>{if(e.target!==map)return;const deltas={ArrowLeft:[-80,0],ArrowRight:[80,0],ArrowUp:[0,-80],ArrowDown:[0,80]};if(deltas[e.key]){e.preventDefault();map.scrollBy(...deltas[e.key]);}if(['+','=','-'].includes(e.key)){e.preventDefault();setZoom(e.key==='-'?-1:1);}});}
  function setZoom(delta){zoom=Math.min(3,Math.max(1,zoom+delta));render();if(selected)centerPlot(selected);saveState();accountContent.querySelector(`[data-town-zoom="${delta}"]`)?.focus({preventScroll:true});}
  function purchaseMarkup(){
    const plot=data.plots.find(plot=>plot.id===selected);if(!plot||plot.occupied)return '';
    const cost=plot.costs[storeType],capacity=storeType==='cars'?plot.carCapacity:plot.capacity,capped=data.myStoreCount>=data.maxStores,locked=account&&(data.playerLevel??1)<plot.requiredLevel;
    return `<div class="town-purchase-content"><button type="button" class="dialog-close" data-town-close aria-label="${t('Close','Schließen')}">×</button><p class="eyebrow">${esc(plot.districtName)}</p><h2 id="town-purchase-title" tabindex="-1">${esc(plot.streetName)}</h2><p class="town-location-size">${esc(sizeName(plot.size))}</p><form class="town-purchase"><fieldset ${purchaseStep===2?'hidden':''}><legend>${t('Store type','Ladentyp')}</legend><div class="town-type-grid">${data.types.map(type=>`<label class="town-type-choice${storeType===type.id?' is-selected':''}"><input type="radio" name="type" value="${type.id}" ${storeType===type.id?'checked':''} ${busy?'disabled':''}>${art.icon(type.id)}<span>${esc(typeName(type.id))}</span>${ui.stockHint(type.id)?`<small class="town-type-hint">${esc(ui.stockHint(type.id))}</small>`:''}</label>`).join('')}</div></fieldset><div class="town-buy-summary" ${purchaseStep===1?'hidden':''}><span>${capacity} ${t('shelf spaces','Regalplätze')}</span><strong>${justizEuro(cost)}</strong></div>${account?`<p class="town-purchase-note">${capped?t('Your store limit is reached.','Dein Ladenlimit ist erreicht.'):locked?t(`Requires level ${plot.requiredLevel}.`,`Benötigt Level ${plot.requiredLevel}.`):account.tokens<cost?t(`You need ${justizEuro(cost-account.tokens)} more.`,`Dir fehlen noch ${justizEuro(cost-account.tokens)}.`):t(`Balance after purchase: ${justizEuro(account.tokens-cost)}.`,`Guthaben nach dem Kauf: ${justizEuro(account.tokens-cost)}.`)}</p><button type="${purchaseStep===1?'button':'submit'}" ${purchaseStep===1?'data-town-review':''} class="primary-button" ${busy||capped||locked||account.tokens<cost?'disabled':''}>${busy?t('Opening…','Wird eröffnet …'):purchaseStep===1?t('Review location','Standort prüfen'):t('Confirm & open store','Bestätigen & Laden eröffnen')} →</button>`:`<a href="/login" data-page class="primary-button">${t('Sign in to open here','Anmelden und hier eröffnen')} →</a>`}<p class="account-error" role="alert"></p></form>${purchaseStep===2?`<button class="secondary-button" data-town-back>${t('Change store type','Ladentyp ändern')}</button>`:''}<details class="town-location-details" ${purchaseStep===2?'open':''}><summary>${t('Location details','Standortdetails')}</summary><dl><div><dt>${t('Required level','Benötigtes Level')}</dt><dd>${plot.requiredLevel}</dd></div><div><dt>${t('Foot traffic','Laufkundschaft')}</dt><dd>${number(plot.trafficMultiplier,2)}×</dd></div><div><dt>${t('Location price','Standortpreis')}</dt><dd>${number(plot.priceMultiplier,2)}×</dd></div><div><dt>${t('Theft fine','Diebstahlbußgeld')}</dt><dd>${number(Math.max(1,1/plot.theftMultiplier),2)}×</dd></div><div><dt>${t('Compatible inventory','Passendes Inventar')}</dt><dd>${data.compatibleStock?.[storeType]||0}</dd></div></dl><p>${t('One store per plot. Store size cannot be changed.','Ein Laden pro Grundstück. Die Ladengröße kann nicht geändert werden.')}</p></details></div>`;
  }
  function paintPurchase(){const expanded=dialog.querySelector('.town-location-details')?.open;dialog.innerHTML=purchaseMarkup();if(expanded&&dialog.querySelector('details'))dialog.querySelector('details').open=true;}
  function openPurchase(id,button=null){const plot=data.plots.find(plot=>plot.id===id);if(!plot||plot.occupied)return;selected=id;purchaseStep=1;returnFocus=button;centerPlot(id);paintPurchase();if(!dialog.open)dialog.showModal();dialog.querySelector('h2')?.focus({preventScroll:true});}
  dialog.addEventListener('close',()=>{if(currentAccountPage!=='/town')return;(returnFocus?.isConnected?returnFocus:accountContent.querySelector('[data-town-view="open"]'))?.focus({preventScroll:true});returnFocus=null;});
  document.addEventListener('click',event=>{if(currentAccountPage!=='/town'||!data)return;const b=event.target.closest('button');if(!b)return;if(b.hasAttribute('data-town-close')){dialog.close();return;}if(b.hasAttribute('data-town-review')){purchaseStep=2;paintPurchase();dialog.querySelector('h2')?.focus();return;}if(b.hasAttribute('data-town-back')){purchaseStep=1;paintPurchase();return;}if(busy)return;if(b.dataset.townSelect){selected=b.dataset.townSelect;if(zoom===1)zoom=2;render();centerPlot(selected);saveState();accountContent.querySelector('.town-selection h2')?.setAttribute('tabindex','-1');accountContent.querySelector('.town-selection h2')?.focus({preventScroll:true});}if(b.dataset.townOpen)openPurchase(b.dataset.townOpen,b);if(b.dataset.townView){view=b.dataset.townView;selected=null;render();saveState();accountContent.querySelector(`[data-town-view="${view}"]`)?.focus();}if(b.dataset.townArea){district=b.dataset.townArea;zoom=2;selected=null;render();centerPlot(visiblePlots()[0]?.id);saveState();}if(b.dataset.townZoom)setZoom(Number(b.dataset.townZoom));if(b.hasAttribute('data-town-fit')){zoom=1;district=null;selected=null;render();saveState();}if(b.hasAttribute('data-town-mine')){view='mine';district=null;zoom=2;selected=data.plots.find(p=>p.business?.own)?.id||null;render();centerPlot(selected);saveState();}if(b.hasAttribute('data-town-clear')){selected=null;render();saveState();}if(b.dataset.townDisplay){listMode=b.dataset.townDisplay==='list';render();saveState();}});
  document.addEventListener('click',event=>{const link=event.target.closest('a[data-page]');if(currentAccountPage!=='/town'||!link||!link.getAttribute('href')?.startsWith('/stores?'))return;saveState();const url=new URL(link.href);url.searchParams.set('returnTo',location.pathname+location.search);link.href=url.pathname+url.search;},true);
  document.addEventListener('change',event=>{if(currentAccountPage!=='/town'||!data||busy)return;const target=event.target;if(target.matches('[data-town-district]')){district=target.value||null;zoom=district?2:1;selected=null;render();if(district)centerPlot(visiblePlots()[0]?.id);saveState();accountContent.querySelector('[data-town-district]')?.focus();}if(target.matches('[data-town-type]')){typeFilter=target.value;selected=null;render();saveState();accountContent.querySelector('[data-town-type]')?.focus();}if(target.matches('.town-purchase [name="type"]')){storeType=target.value;paintPurchase();dialog.querySelector(`[value="${storeType}"]`)?.focus();}});
  document.addEventListener('submit',async event=>{if(currentAccountPage!=='/town'||!event.target.matches('.town-purchase'))return;event.preventDefault();if(busy||!account||purchaseStep!==2)return;const plot=data.plots.find(p=>p.id===selected);if(!plot||plot.occupied)return;const visit=accountVisit,owner=account.id;busy=true;paintPurchase();try{const result=await accountApi('businesses/buy',{plotId:plot.id,type:storeType});if(visit!==accountVisit||owner!==account?.id)return;updateAccount(result.user);saveState();await navigateAccountPage('/businesses');showToast(t('Store opened. Add stock to start trading.','Laden eröffnet. Räume Waren ein, um loszulegen.'));}catch(error){if(visit===accountVisit&&owner===account?.id){await refresh(visit,false).catch(()=>{});busy=false;if(!purchaseMarkup()){dialog.close();render();showToast(error.message);}else{paintPurchase();dialog.querySelector('.account-error').textContent=error.message;}}}finally{if(visit===accountVisit)busy=false;}});
  window.addEventListener('resize',()=>{if(currentAccountPage==='/town'&&data)sizeMap();});
  document.addEventListener('jg:language',()=>{if(currentAccountPage==='/town'){render();if(dialog.open)paintPurchase();}});
  return {load,stop,render};
})();
